    public static int cfFailEnum(int k, emon.Enctx.Cfg c) {
        // `ocr is always, auto or never`: the words come from the table, in its order.
        cfPutKey(k, c);
        emon.Port.textAscii(c.msg, " is ");
        int m = 0;
        int seen = 0;
        int r = 0;
        while (r < 13) {
            if (CV_ROWS[r * 4 + 0] == k) {
                m += 1;
            }
            r += 1;
        }
        r = 0;
        while (r < 13) {
            if (CV_ROWS[r * 4 + 0] == k) {
                if (seen > 0) {
                    if (seen == (m - 1)) {
                        emon.Port.textAscii(c.msg, " or ");
                    } else {
                        emon.Port.textAscii(c.msg, ", ");
                    }
                }
                cfPutWord(r, c);
                seen += 1;
            }
            r += 1;
        }
        return 0;
    }
