    public static int cfApply(emon.Port.Cells t, int k, int kf, int ke, int vf, int vt, emon.Enctx.Cfg c) {
        // The line t[kf, ke) = t[vf, vt) for key k: 1, or 0 with the sentence in `msg`.
        int shape = CK_ROWS[k * 5 + 0];
        if (shape == SH_STR) {
            emon.Port.cellsDrop(c.lcl, 0);
            c.haveloc = 1;
            int i = vf;
            while (i < vt) {
                emon.Port.cellsPush(c.lcl, emon.Port.cellsAt(t, i));
                i += 1;
            }
            return 1;
        }
        if (shape == SH_NUM) {
            if (cfNum(t, vf, vt, c) == 0) {
                cfFailNum(t, kf, ke, vf, vt, c);
                return 0;
            }
            if ((c.num < CK_ROWS[k * 5 + 1]) || (c.num > CK_ROWS[k * 5 + 2])) {
                cfFailRange(t, kf, ke, CK_ROWS[k * 5 + 1], CK_ROWS[k * 5 + 2], c);
                return 0;
            }
            cfSetNum(c, k, c.num);
            return 1;
        }
        if (shape == SH_ENUM) {
            int code = cfWord(t, vf, vt, k);
            if (code < 0) {
                cfFailEnum(k, c);
                return 0;
            }
            cfSetWord(c, k, code);
            return 1;
        }
        if (shape == SH_FLAG) {
            cfSetFlag(c, k, cfOne(t, vf, vt));
            return 1;
        }
        if (shape == SH_LIMIT) {
            int kind = cfLimitFind(t, kf + CK_ROWS[k * 5 + 4], ke);
            if (kind < 0) {
                emon.Port.textAscii(c.msg, "no limit named ");
                cfPutSpan(t, kf + CK_ROWS[k * 5 + 4], ke, c);
                return 0;
            }
            if (cfNum(t, vf, vt, c) == 0) {
                cfFailNum(t, kf, ke, vf, vt, c);
                return 0;
            }
            if ((c.num < Limits.LM_ROWS[kind * 6 + 1]) || (c.num > Limits.LM_ROWS[kind * 6 + 2])) {
                cfFailRange(t, kf, ke, Limits.LM_ROWS[kind * 6 + 1], Limits.LM_ROWS[kind * 6 + 2], c);
                return 0;
            }
            emon.Port.cellsPush(c.lims, kind);
            emon.Port.cellsPush(c.lims, c.num);
            return 1;
        }
        int nf = kf + CK_ROWS[k * 5 + 4];
        int q = 0;
        emon.Port.cellsPush(c.prod, ke - nf);
        emon.Port.cellsPush(c.prod, vt - vf);
        q = nf;
        while (q < ke) {
            emon.Port.cellsPush(c.prod, emon.Port.cellsAt(t, q));
            q += 1;
        }
        q = vf;
        while (q < vt) {
            emon.Port.cellsPush(c.prod, emon.Port.cellsAt(t, q));
            q += 1;
        }
        return 1;
    }
    public static int cfLine(emon.Port.Cells t, int from, int to, emon.Enctx.Cfg c) {
        // One non-empty line: 1, or 0 with the sentence in `msg`.
        int eq = from;
        while ((eq < to) && (emon.Port.cellsAt(t, eq) != 61)) {
            eq += 1;
        }
        if (eq == to) {
            emon.Port.textAscii(c.msg, "option \"");
            cfPutSpan(t, from, to, c);
            emon.Port.textAscii(c.msg, "\" has no value");
            return 0;
        }
        int k = cfKeyFind(t, from, eq);
        if (k < 0) {
            emon.Port.textAscii(c.msg, "unknown option ");
            cfPutSpan(t, from, eq, c);
            return 0;
        }
        return cfApply(t, k, from, eq, eq + 1, to, c);
    }
    public static int cfParse(emon.Port.Cells t, emon.Enctx.Cfg c) {
        // Fill `c` from the options text `t` (code points): the defaults, then each line. Answers 0, or 1 with the sentence in `(fd c msg)`.
        cfDefaults(c);
        int n = emon.Port.cellsLen(t);
        int at = 0;
        while (at < n) {
            int le = at;
            int hi = at;
            while ((le < n) && (emon.Port.cellsAt(t, le) != 10)) {
                le += 1;
            }
            hi = le;
            if ((hi > at) && (emon.Port.cellsAt(t, hi - 1) == 13)) {
                hi -= 1;
            }
            if (hi > at) {
                if (cfLine(t, at, hi, c) == 0) {
                    return 1;
                }
            }
            at = le + 1;
        }
        return 0;
    }
    public static int cfIsKey(emon.Port.Cells t, int from, int to) {
        // 1 when t[from, to) names a key of the grammar (a driver asks it of `--NAME=`).
        if (cfKeyFind(t, from, to) < 0) {
            return 0;
        }
        return 1;
    }
